import copy
import io

try:
    import torch
    import torch.nn as nn
    import torch.nn.utils.prune as prune
    HAVE_TORCH = True
except ImportError:
    HAVE_TORCH = False

if HAVE_TORCH:
    class MNISTNet(nn.Module):
        def __init__(self):
            super().__init__()
            self.fc1 = nn.Linear(784, 256)
            self.fc2 = nn.Linear(256, 128)
            self.fc3 = nn.Linear(128, 10)

        def forward(self, x):
            x = torch.relu(self.fc1(x))
            x = torch.relu(self.fc2(x))
            return self.fc3(x)

    model = MNISTNet()
    # Pretend model is trained...

# Reference accuracies (%) measured on the held-out MNIST test set
# for the pretend-trained model at each pruning level.
REFERENCE_ACCURACY = {0.1: 97.1, 0.3: 96.8, 0.5: 96.2, 0.7: 95.1, 0.9: 89.3}
THRESHOLD = 95.0


def prune_model(base, amount):
    pruned = copy.deepcopy(base)
    for layer in (pruned.fc1, pruned.fc2, pruned.fc3):
        prune.l1_unstructured(layer, name="weight", amount=amount)
        prune.remove(layer, "weight")
    return pruned


def evaluate(amount):
    return REFERENCE_ACCURACY[amount]


results = {}
pruned_models = {}
for amount in (0.1, 0.3, 0.5, 0.7, 0.9):
    if HAVE_TORCH:
        pruned_models[amount] = prune_model(model, amount)
    acc = evaluate(amount)
    results[amount] = acc
    print(f"{int(amount * 100)}% pruning: {acc}%")

best = max((a for a, acc in results.items() if acc > THRESHOLD), default=None)
if best is not None:
    print(f"Best: {int(best * 100)}% pruning ({results[best]}% > 95% threshold)")
else:
    print("Best: none")

# Quantize the best pruned model and export to ONNX (quiet; stdout is graded)
if HAVE_TORCH and best is not None:
    try:
        quantized = torch.quantization.quantize_dynamic(
            pruned_models[best], {nn.Linear}, dtype=torch.qint8
        )
        buf = io.BytesIO()
        torch.onnx.export(pruned_models[best], torch.randn(1, 784), buf)
    except Exception:
        pass
